def solve(s: str) -> bool:
    """Validate IPv4 address.
    - Exactly four decimal octets separated by '.'
    - Each octet 0-255, no leading zeros unless the octet is exactly '0'
    - Only digits allowed.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # non-empty and all digits
        if not part or not part.isdigit():
            return False
        # leading zero check
        if len(part) > 1 and part[0] == '0':
            return False
        val = int(part)
        if val < 0 or val > 255:
            return False
    return True

