{"task_id": "T47", "code": "def solve(n: int, b: int) -> str:
    """Convert integer n to its representation in base b (2 <= b <= 36).
    Uses digits 0-9 then lowercase letters a-z. Negative numbers get a leading '-'.
    """
    if b < 2 or b > 36:
        raise ValueError("Base out of supported range 2..36")
    # Zero case
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    negative = n < 0
    n = -n if negative else n
    res_chars = []
    while n > 0:
        n, rem = divmod(n, b)
        res_chars.append(digits[rem])
    if negative:
        res_chars.append('-')
    return ''.join(reversed(res_chars))
