def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports +, -, *, / where division truncates toward zero.
    Tokens are strings representing integers or operators.
    """
    stack = []
    for tok in tokens:
        if tok in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
                # Perform integer division truncating toward zero
                # Using int(a / b) works for both positive and negative
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                stack.append(int(a / b))
        else:
            stack.append(int(tok))
    return stack[-1] if stack else 0

