def solve(n, edges):
    """Shortest path weight from node 0 to node n-1 in an undirected weighted graph.
    Returns -1 if node n-1 is unreachable or if the graph is empty (n == 0).
    """
    import heapq
    if n == 0:
        return -1
    if n == 1:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        # Validate indices and weight (allow zero weight)
        if 0 <= a < n and 0 <= b < n and w >= 0:
            adj[a].append((b, w))
            adj[b].append((a, w))
    INF = 10**18
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist[n-1] if dist[n-1] != INF else -1
